/**
 * TMDB posters for the cartoon / movie / TV words of مين برا السالفة؟.
 * posters.json holds only metadata (TMDB id, type, poster path, title), generated by
 * scripts/fetch-posters.ts (GitHub workflow "Refresh TMDB posters"). The images come from
 * TMDB's CDN: proxied by the server edition, loaded directly in the GitHub Pages edition.
 */
import { existsSync, readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { POSTER_PATH_RE } from '../../content/tmdb.ts';

export const POSTER_CATEGORIES = ['cartoons', 'movies', 'tv'];
// KHABSA_POSTERS_FILE: tests only (a fixture list)
export const POSTERS_FILE = process.env.KHABSA_POSTERS_FILE || join(dirname(fileURLToPath(import.meta.url)), 'posters.json');

export interface PosterEntry {
  tmdbId: number;
  type: 'movie' | 'tv';
  path: string;
  title?: string;
}

/** word → poster (valid entries only). */
export function loadPosters(file = POSTERS_FILE): Map<string, PosterEntry> {
  const out = new Map<string, PosterEntry>();
  if (!existsSync(file)) return out;
  const raw = JSON.parse(readFileSync(file, 'utf8')) as Record<string, PosterEntry | null>;
  for (const [word, p] of Object.entries(raw)) {
    if (!p || !Number.isInteger(p.tmdbId) || p.tmdbId <= 0 || (p.type !== 'movie' && p.type !== 'tv') || !POSTER_PATH_RE.test(p.path)) continue;
    out.set(word, { tmdbId: p.tmdbId, type: p.type, path: p.path, ...(p.title ? { title: String(p.title).slice(0, 120) } : {}) });
  }
  return out;
}
